import { expect, test } from "@playwright/test";
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { useTestSession } from "./session";

test("el QR renderizado del PDF abre su servicio con el lector real", async ({ page, context }) => {
  await useTestSession(context);
  // Fixture captured from the consolidated PDF generated by ResultsService.
  const src = `data:image/png;base64,${(await readFile(join(__dirname, "fixtures/qr-service-73.png"))).toString("base64")}`;
  await page.goto("/servicios");
  await page.evaluate((imageSource) => {
    Object.defineProperty(navigator.mediaDevices, "getUserMedia", {
      configurable: true,
      value: async () => {
        const canvas = document.createElement("canvas"); canvas.width = 640; canvas.height = 480;
        const context = canvas.getContext("2d")!;
        context.fillStyle = "white"; context.fillRect(0, 0, 640, 480);
        const image = new Image(); image.src = imageSource; await image.decode();
        context.drawImage(image, 140, 60, 360, 360);
        const stream = canvas.captureStream(10);
        (window as typeof window & { qrCameraTrack: MediaStreamTrack }).qrCameraTrack = stream.getVideoTracks()[0];
        return stream;
      },
    });
  }, src);
  await page.getByRole("button", { name: "Escanear recibo", exact: true }).click();
  await page.getByRole("button", { name: "Activar cámara" }).click();
  await expect(page).toHaveURL(/\/servicios\/detalle\?id=73/);
  await expect(page.getByText("QR-DEMO-73", { exact: true }).first()).toBeVisible();
  expect(await page.evaluate(() => (window as typeof window & { qrCameraTrack: MediaStreamTrack }).qrCameraTrack.readyState)).toBe("ended");
});
